// BeforePlaybackStartEvent - 回放前（可取消）
mm.on('io.github.samera2022.samacros.api.event.events.BeforePlaybackStartEvent', 
    (event) => {
        mm.log('重复次数：' + event.getRepeatCount());
        if (event.getRepeatCount() > 1000) {
            event.setCancelled(true);  // 取消回放
            mm.log('重复次数过多，已取消！');
        }
    });

// OnLoopCompleteEvent - 循环完成
mm.on('io.github.samera2022.samacros.api.event.events.OnLoopCompleteEvent', 
    (event) => {
        const completed = event.getCompletedIterations();
        const remaining = event.getRemainingIterations();
        mm.log('循环 ' + completed + ' 完成，剩余 ' + remaining + ' 次');
    });

