    (event) => {
        const completed = event.getCompletedIterations();
        const remaining = event.getRemainingIterations();
        const elapsed = event.getTimestamp() - startTime;

        const percent = Math.round((completed / (completed + remaining)) * 100);
        mm.log('[' + percent + '%] 循环 ' + completed + ' - ' + 
                Math.round(elapsed / 1000) + 's 已过');
    });

examples.example2-code:
const registry_name = 'safe_executor';
const display_name = '安全执行器';
const version = '1.0.0';
const author = 'Your Name';
const description = '执行前验证';

const MAX_REPEATS = 100;
const MIN_ACTIONS = 1;

mm.on('io.github.samera2022.samacros.api.event.events.BeforePlaybackStartEvent', 
    (event) => {
        try {
            const repeats = event.getRepeatCount();
            const context = mm.getContext();
            const macro = context.getMacroInfo();
            const actions = macro.getActionsCount();

            // 检查重复次数
            if (repeats < 1 || repeats > MAX_REPEATS) {
                event.setCancelled(true);
                context.showToast('错误', '无效的重复次数：' + repeats);
                mm.log('已阻止：无效的重复次数');
                return;
            }

            // 检查操作数量
            if (actions < MIN_ACTIONS) {
                event.setCancelled(true);
                context.showToast('错误', '宏为空');
                mm.log('已阻止：宏中无操作');
                return;
            }

            mm.log('已批准：' + repeats + '次，包含 ' + actions + ' 个操作');
            context.showToast('准备好', '回放已验证');

        } catch (error) {
            event.setCancelled(true);
            mm.log('错误：' + error);
        }
    });

