            const color = context.getPixelColor(CHECK_X, CHECK_Y);

            if (color.getRed() === TARGET_RED &&
                color.getGreen() === TARGET_GREEN &&
                color.getBlue() === TARGET_BLUE) {

                mm.log('在迭代 ' + event.getCompletedIterations() + ' 发现目标颜色');
                context.showToast('发现', '检测到目标颜色！');
            }
        }
    });

